                { text = "Count your rounds before you need them.", weight = 1 },
                { text = "I miss coffee that didn't taste like a burnt tire.", weight = 1 },
                { text = "A locked door is a promise. Usually a bad one.", weight = 1 },
                { text = "Tomorrow we check the pharmacy. Today we stay alive.", weight = 1 },
